# -*- coding: utf-8 -*-
"""Writes all addon settings to <profile>/settings.json for the Elementum binary (-configPath).

The shape mirrors Elementum's ConfigBundle (config/types.go). Never log setting values: they hold secrets.
"""
import binascii
import io
import json
import os
import subprocess
import threading
import xml.etree.ElementTree as ET

FILE_VERSION = 1
FILE_NAME = "settings.json"
BASELINE_NAME = "settings.addon-state.json"  # write-back values the addon last wrote
SUPPORT_MARKER = b"settings-file-v1"
# Kodi UI languages Go maps by English-name prefix (xbmc/types.go languageMappings)
LANGUAGE_MAPPINGS = {"chinese": "zh", "english": "en", "french": "fr", "hindi": "hi", "mongolian": "mn",
                     "persian": "fa", "portuguese": "pt", "serbian": "sr", "spanish": "es", "tamil": "ta"}
# Settings the binary writes back itself: token group per service, newest expiry wins
TOKEN_SERVICES = ("trakt", "simkl", "mdblist", "scrob", "opensubtitles")
WRITEBACK_KEYS = tuple(k for p in TOKEN_SERVICES for k in (p + "_token", p + "_refresh_token", p + "_token_expiry", p + "_username"))
_support = {}


def collect_settings(settings_xml, get_setting, translate):
    """Every id in settings.xml, typed like Elementum's fetchConfiguration; folders are made absolute."""
    out = {}
    for el in ET.parse(settings_xml).getroot().iter("setting"):
        key, typ, opt = el.get("id"), el.get("type"), el.get("option")
        if not key:
            continue
        val = get_setting(key) or ""
        if typ in ("enum", "number"):
            try:
                out[key] = int(val)
            except ValueError:
                out[key] = 0
        elif typ == "slider":
            try:
                f = float(val)
            except ValueError:
                f = 0.0
            out[key] = f if opt == "float" and f > 0 else int(f)
        elif typ == "bool":
            out[key] = (val == "true")
        elif typ == "folder" and val:
            out[key] = translate(val)
        else:
            out[key] = val
    return out


def kodi_buffer_size(advanced_xml):
    """memorysize / cachemembuffersize from advancedsettings.xml, 0 when absent (as Elementum does)."""
    try:
        cache = ET.parse(advanced_xml).getroot().find("cache")
        for tag in ("cachemembuffersize", "memorysize"):
            v = int(cache.findtext(tag) or 0)
            if v > 0:
                return v
    except Exception:
        pass
    return 0


def language_of(settings, name, kodi_default):
    value = settings.get(name) or ""
    return value.split(" | ")[1] if " | " in value else kodi_default


def write_atomic(path, obj):
    tmp = "%s.%d.%s.tmp" % (path, os.getpid(), binascii.hexlify(os.urandom(4)).decode())
    fd = os.open(tmp, os.O_WRONLY | os.O_CREAT | os.O_TRUNC, 0o600)
    try:
        with io.open(fd, "w", encoding="utf-8") as f:
            f.write(u"%s" % json.dumps(obj, indent=2, ensure_ascii=False))
            f.flush()
            os.fsync(f.fileno())
        if hasattr(os, "replace"):
            os.replace(tmp, path)
        else:
            _py2_replace(tmp, path)
    except Exception:
        try:
            os.remove(tmp)
        except OSError:
            pass
        raise


def _py2_replace(src, dst):
    # shortcut: not atomic on Windows py2 (os.rename fails if dst exists); Kodi 19+ is py3
    if os.name == "nt" and os.path.exists(dst):
        os.remove(dst)
    os.rename(src, dst)


def binary_supports_config_path(binary, **popen_kwargs):
    """Capability probe: `-help` must print the marker (older binaries print configPath without file support).

    popen_kwargs: the same env/cwd/startupinfo as the real start. Cached per (path, mtime, size);
    a failed probe is not cached and means the old launch."""
    try:
        st = os.stat(binary)
        key = (binary, st.st_mtime, st.st_size)
        if key not in _support:
            proc = subprocess.Popen([binary, "-help"], stdout=subprocess.PIPE, stderr=subprocess.STDOUT, **popen_kwargs)
            killed = []
            timer = threading.Timer(5, lambda: (killed.append(1), proc.kill()))
            timer.start()
            out = proc.communicate()[0]  # flag parsers may exit non-zero after printing help
            timer.cancel()
            if killed:
                return False  # timeout is not a definite answer: do not cache
            _support[key] = SUPPORT_MARKER in out
        return _support[key]
    except Exception:
        return False


def _expiry(v):
    try:
        return int(v)
    except (TypeError, ValueError):
        return 0


def _group(d, p):
    return dict((k, u"%s" % d[k]) for k in WRITEBACK_KEYS if k.startswith(p + "_") and k in d)


def keep_newer_tokens(settings, existing, baseline, set_setting):
    """The binary writes tokens back into the file. baseline = what the addon wrote last time: a file group that
    differs from it was changed by the binary (refresh or deauth), so it wins and is pushed to Kodi.
    Otherwise Kodi wins (user change). Without a baseline fall back to the newer expiry."""
    for p in TOKEN_SERVICES:
        file_group = _group(existing, p)
        if baseline is not None:
            binary_changed = file_group != _group(baseline, p)
        else:
            ek = p + "_token_expiry"
            binary_changed = ek in existing and _expiry(existing[ek]) > _expiry(settings.get(ek))
        if binary_changed:
            for k in file_group:
                if k in settings:
                    settings[k] = existing[k]
                    set_setting(k, file_group[k])


def kodi_language(get_language):
    english = (get_language("english", False) or "").lower()
    for k, v in LANGUAGE_MAPPINGS.items():
        if english.startswith(k):
            return v
    return get_language("iso", False) or "en"


def kodi_interface_language(get_language):
    """Kodi's interface language with its region ("pt-br"): Elementum translates its texts for Kodi into it.
    The "language" setting is the metadata language and can differ."""
    return (get_language("iso", True) or kodi_language(get_language)).lower()


def kodi_region(get_language):
    region = get_language("iso", True) or ""
    region = region.split("-", 1)[1] if "-" in region else region  # as Go: no dash keeps the whole value
    return (region or "us").upper()


def library_supports_config_path(path):
    """Shared library cannot run -help: look for the marker in its bytes (cached per path+mtime+size)."""
    try:
        st = os.stat(path)
        key = ("lib", path, st.st_mtime, st.st_size)
        if key not in _support:
            found, tail = False, b""
            with open(path, "rb") as f:
                for chunk in iter(lambda: f.read(1 << 20), b""):
                    if SUPPORT_MARKER in tail + chunk:
                        found = True
                        break
                    tail = chunk[-len(SUPPORT_MARKER):]
            _support[key] = found
        return _support[key]
    except Exception:
        return False


def build_bundle(addon_path, addon_info, platform, translate, get_setting, get_language, existing=None, set_setting=None, baseline=None):
    """get_language(kind, with_region), kind "iso"/"english" -> xbmc.getLanguage(ISO_639_1/ENGLISH_NAME, with_region).
    existing: Settings dict of the current settings.json (for keep_newer_tokens)."""
    settings = collect_settings(os.path.join(addon_path, "resources", "settings.xml"), get_setting, translate)
    if existing and set_setting:
        keep_newer_tokens(settings, existing, baseline, set_setting)
    for key, val in settings.items():  # default special://temp/... folders must exist (Elementum made them via Kodi)
        if key in ("download_path", "library_path", "torrents_path") and val:
            try:
                os.makedirs(val)
            except OSError:
                pass
    info = dict((k.capitalize(), addon_info(k)) for k in (
        "author", "changelog", "description", "disclaimer", "fanart", "icon", "name", "stars", "summary", "type", "version"))
    info.update({
        "ID": addon_info("id"),
        "Path": addon_path,
        "Profile": translate(addon_info("profile")),
        "Home": translate("special://home"),
        "Xbmc": translate("special://xbmc"),
        "TempPath": os.path.join(translate("special://temp"), "elementum"),
    })
    language = language_of(settings, "language", kodi_language(get_language))
    second = language_of(settings, "second_language", "en")
    if language.startswith(second) or second.startswith(language):
        second = ""
    return {
        "Version": FILE_VERSION,
        "Info": info,
        "Platform": {
            "OS": platform.get("os", ""), "Arch": platform.get("arch", ""), "Version": platform.get("version", ""),
            "Kodi": platform.get("kodi", 0), "Build": platform.get("build", ""),
        },
        "Settings": settings,
        "Language": language,
        "SecondLanguage": second,
        "Region": kodi_region(get_language),
        "InterfaceLanguage": kodi_interface_language(get_language),
        "KodiBufferSize": kodi_buffer_size(os.path.join(translate("special://userdata"), "advancedsettings.xml")),
    }


def write_settings_file():
    """Collect and write; returns the file path, or None on failure (value-free logging)."""
    from elementum.addon import ADDON, ADDON_PATH
    from elementum.logger import log
    from elementum.osarch import PLATFORM
    from elementum.util import translatePath
    from kodi_six import xbmc
    try:
        path = os.path.join(translatePath(ADDON.getAddonInfo("profile")), FILE_NAME)
        if not os.path.isdir(os.path.dirname(path)):
            os.makedirs(os.path.dirname(path))
        try:
            with io.open(path, encoding="utf-8") as f:
                existing = json.load(f).get("Settings")
        except Exception:
            existing = None
        base_path = os.path.join(os.path.dirname(path), BASELINE_NAME)
        try:
            with io.open(base_path, encoding="utf-8") as f:
                baseline = json.load(f)
        except Exception:
            baseline = None
        bundle = build_bundle(
            ADDON_PATH, ADDON.getAddonInfo, PLATFORM, translatePath, ADDON.getSetting,
            lambda kind, region: xbmc.getLanguage(xbmc.ENGLISH_NAME if kind == "english" else xbmc.ISO_639_1, region),
            existing, ADDON.setSetting, baseline)
        write_atomic(path, bundle)
        write_atomic(base_path, dict((k, v) for k, v in bundle["Settings"].items() if k in WRITEBACK_KEYS))
        return path
    except Exception as e:
        log.error("Unable to write %s: %s" % (FILE_NAME, repr(e)))
        return None
